BEGIN;
CREATE FUNCTION encova_finance_posted_source_read(actor UUID,input JSONB) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE e public."FinanceJournalEntry"%ROWTYPE;total INTEGER;page INTEGER;pages INTEGER;rows JSONB;debits NUMERIC;credits NUMERIC;workflow JSONB;document_kind TEXT;document_id UUID;resource TEXT;original UUID;source_digest TEXT;BEGIN
 IF NOT EXISTS(SELECT 1 FROM public."Person" WHERE id=actor AND role='SUPER_ADMIN' AND status='ACTIVE') OR NOT EXISTS(SELECT 1 FROM public."FinanceGrant" WHERE "userId"=actor AND "revokedAt" IS NULL) THEN RAISE EXCEPTION 'FINANCE_FORBIDDEN' USING ERRCODE='P0001';END IF;
 IF jsonb_typeof(input) IS DISTINCT FROM 'object' OR input-ARRAY['id','page']<>'{}'::jsonb OR jsonb_typeof(input->'id') IS DISTINCT FROM 'string' OR jsonb_typeof(input->'page') IS DISTINCT FROM 'number' OR(input->>'page')::integer NOT BETWEEN 1 AND 10000 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 SELECT * INTO e FROM public."FinanceJournalEntry" WHERE id=(input->>'id')::uuid;IF e.id IS NULL THEN RAISE EXCEPTION 'FINANCE_NOT_FOUND' USING ERRCODE='P0001';END IF;
 original:=public.encova_finance_cash_flow_original(e.id);document_id:=e."sourceId";
 IF e."sourceType"='CUSTOMER_DOCUMENT' THEN
  SELECT coalesce(o.kind,c.kind),coalesce(o.id,c.id) INTO document_kind,document_id FROM public."FinanceCustomerDocument" c LEFT JOIN public."FinanceCustomerDocument" o ON o.id=c."reversalOfId" WHERE c.id=e."sourceId";
  resource:=CASE document_kind WHEN 'RECEIPT' THEN 'receipts' WHEN 'ADVANCE_APPLICATION' THEN 'advance-applications' WHEN 'CUSTOMER_CREDIT' THEN 'customer-credits' WHEN 'CUSTOMER_REFUND' THEN 'customer-refunds' WHEN 'UNALLOCATION' THEN 'receipt-unallocations' END;
 ELSIF e."sourceType"='SUPPLIER_DOCUMENT' THEN
  SELECT coalesce(o.kind,c.kind),coalesce(o.id,c.id) INTO document_kind,document_id FROM public."FinanceSupplierDocument" c LEFT JOIN public."FinanceSupplierDocument" o ON o.id=c."reversalOfId" WHERE c.id=e."sourceId";
  resource:=CASE document_kind WHEN 'PAYMENT' THEN 'supplier-payments' WHEN 'ADVANCE_APPLICATION' THEN 'supplier-applications' WHEN 'SUPPLIER_CREDIT' THEN 'supplier-credits' WHEN 'SUPPLIER_REFUND' THEN 'supplier-refunds' WHEN 'UNALLOCATION' THEN 'supplier-releases' END;
 ELSIF e."sourceType"='MOVEMENT' THEN
  SELECT coalesce(o.kind,c.kind),coalesce(o.id,c.id) INTO document_kind,document_id FROM public."FinanceMovement" c LEFT JOIN public."FinanceMovement" o ON o.id=c."reversalOfId" WHERE c.id=e."sourceId";resource:='movements';
 ELSIF e."sourceType"='ASSET_MOVEMENT' THEN
  SELECT coalesce(o.kind,c.kind),coalesce(o.id,c.id) INTO document_kind,document_id FROM public."FinanceAssetMovement" c LEFT JOIN public."FinanceAssetMovement" o ON o.id=c."reversalOfId" WHERE c.id=e."sourceId";resource:='asset-movements';
 ELSIF e."sourceType"='JOURNAL_DRAFT' THEN resource:='journals';
 ELSIF e."sourceType"='JOURNAL_REVERSAL' THEN SELECT "draftId" INTO document_id FROM public."FinanceJournalEntry" WHERE id=e."reversalOfId";IF document_id IS NOT NULL THEN resource:='journals';END IF;
 ELSE resource:=CASE e."sourceType" WHEN 'INVOICE' THEN 'invoices' WHEN 'BILL' THEN 'bills' WHEN 'COST_ALLOCATION' THEN 'cost-allocations' END;END IF;
 IF resource IS NOT NULL AND document_id IS NOT NULL THEN workflow:=jsonb_build_object('href','/finance/'||resource||'/'||document_id::text,'kind',coalesce(document_kind,e."sourceType"),'original',original IS NOT NULL);END IF;
 SELECT count(*),coalesce(sum(debit),0),coalesce(sum(credit),0),encode(sha256(convert_to(coalesce(jsonb_agg(jsonb_build_object('id',id,'sequence',sequence,'accountId',"accountId",'debit',debit::text,'credit',credit::text,'projectId',"projectId",'partyId',"partyId") ORDER BY sequence,id),'[]'::jsonb)::text,'UTF8')),'hex') INTO total,debits,credits,source_digest FROM public."FinanceJournalLine" WHERE "journalId"=e.id;
 pages:=greatest(1,ceil(total/25.0)::integer);page:=least((input->>'page')::integer,pages);
 SELECT coalesce(jsonb_agg(to_jsonb(b) ORDER BY b.sequence,b.id),'[]'::jsonb) INTO rows FROM(SELECT l.id,l.sequence,l."accountId",a.code,a.name AS "accountName",a.active AS "accountActive",l.description,l.debit::text AS debit,l.credit::text AS credit,l."projectId",p.name AS "projectName",l."partyId",party.name AS "partyName" FROM public."FinanceJournalLine" l JOIN public."FinanceAccount" a ON a.id=l."accountId" LEFT JOIN public."Project" p ON p.id=l."projectId" LEFT JOIN public."FinanceParty" party ON party.id=l."partyId" WHERE l."journalId"=e.id ORDER BY l.sequence,l.id LIMIT 25 OFFSET(page-1)*25)b;
 RETURN jsonb_build_object('metadata',public.encova_finance_report_metadata(e."postingDate",e."postingDate",jsonb_build_object('report','POSTED_SOURCE','journalId',e.id,'sourceLineDigest',source_digest)),'entry',jsonb_build_object('id',e.id,'reference',e.reference,'sourceType',e."sourceType",'sourceId',e."sourceId",'sourceAction',e."sourceAction",'postingDate',e."postingDate",'postedAt',e."postedAt",'postedBy',(SELECT "displayName" FROM public."Person" WHERE id=e."postedById"),'description',e.description,'evidence',e.evidence,'originalJournalId',original),'workflow',workflow,'debitTotal',round(debits,2)::text,'creditTotal',round(credits,2)::text,'difference',round(debits-credits,2)::text,'items',rows,'total',total,'page',page,'pages',pages);
 EXCEPTION WHEN data_exception THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END $$;
CREATE FUNCTION encova_finance_rollforward_events(report_kind TEXT,cutoff DATE) RETURNS TABLE("eventKey" TEXT,"entityId" UUID,"accountId" UUID,metric TEXT,"effectiveDate" DATE,delta NUMERIC,"journalId" UUID,"sourceType" TEXT,"sourceId" UUID,reference TEXT,description TEXT) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
SELECT v.id::text,v."partyId",v."accountId",v.bucket,v."effectiveDate",v.amount,e.id,e."sourceType",e."sourceId",e.reference,e.description FROM public."FinanceFundingEvent" v JOIN public."FinanceJournalEntry" e ON e.id=v."journalId" WHERE report_kind='FUNDING' AND v."effectiveDate"<=cutoff
UNION ALL
SELECT v.id::text,v."loanId",CASE WHEN v.bucket='PRINCIPAL' THEN l."principalAccountId" ELSE l."interestAccountId" END,l.direction||'_'||v.bucket,v."effectiveDate",v.amount,e.id,e."sourceType",e."sourceId",e.reference,e.description FROM public."FinanceLoanEvent" v JOIN public."FinanceLoan" l ON l.id=v."loanId" JOIN public."FinanceJournalEntry" e ON e.id=v."journalId" WHERE report_kind='LOANS' AND v."effectiveDate"<=cutoff
UNION ALL
SELECT v.id::text,v."sourceDocumentId",v."accountId",'CLIENT_ADVANCE',v."effectiveDate",v.amount,e.id,e."sourceType",e."sourceId",e.reference,e.description FROM public."FinanceClientBalanceEvent" v JOIN public."FinanceJournalEntry" e ON e.id=v."journalId" WHERE report_kind='ADVANCES' AND v."effectiveDate"<=cutoff
UNION ALL
SELECT v.id::text,v."sourceDocumentId",v."accountId",'SUPPLIER_ADVANCE',v."effectiveDate",v.amount,e.id,e."sourceType",e."sourceId",e.reference,e.description FROM public."FinanceSupplierBalanceEvent" v JOIN public."FinanceJournalEntry" e ON e.id=v."journalId" WHERE report_kind='ADVANCES' AND v."effectiveDate"<=cutoff
UNION ALL
SELECT v.id::text||':COST',v."holdingId",h."investmentAccountId",'COST',v."effectiveDate",v."costDelta",v."journalId",'MOVEMENT',v."movementId",coalesce(e.reference,m.number),m.description FROM public."FinanceInvestmentEvent" v JOIN public."FinanceInvestmentHolding" h ON h.id=v."holdingId" JOIN public."FinanceMovement" m ON m.id=v."movementId" LEFT JOIN public."FinanceJournalEntry" e ON e.id=v."journalId" WHERE report_kind='INVESTMENTS' AND v."effectiveDate"<=cutoff AND v."costDelta" IS NOT NULL
UNION ALL
SELECT v.id::text||':CARRYING',v."holdingId",h."investmentAccountId",'CARRYING',v."effectiveDate",v."carryingDelta",v."journalId",'MOVEMENT',v."movementId",coalesce(e.reference,m.number),m.description FROM public."FinanceInvestmentEvent" v JOIN public."FinanceInvestmentHolding" h ON h.id=v."holdingId" JOIN public."FinanceMovement" m ON m.id=v."movementId" LEFT JOIN public."FinanceJournalEntry" e ON e.id=v."journalId" WHERE report_kind='INVESTMENTS' AND v."effectiveDate"<=cutoff AND v."carryingDelta" IS NOT NULL
UNION ALL
SELECT v.id::text||':UNITS',v."holdingId",NULL::uuid,'UNITS',v."effectiveDate",v."unitsDelta",v."journalId",'MOVEMENT',v."movementId",coalesce(e.reference,m.number),m.description FROM public."FinanceInvestmentEvent" v JOIN public."FinanceInvestmentHolding" h ON h.id=v."holdingId" JOIN public."FinanceMovement" m ON m.id=v."movementId" LEFT JOIN public."FinanceJournalEntry" e ON e.id=v."journalId" WHERE report_kind='INVESTMENTS' AND v."effectiveDate"<=cutoff AND v."unitsDelta" IS NOT NULL
UNION ALL
SELECT v.id::text||':INCOME',v."holdingId",h."incomeControlAccountId",'INCOME_RECEIVABLE',v."effectiveDate",v.amount,e.id,e."sourceType",e."sourceId",e.reference,e.description FROM public."FinanceInvestmentIncomeEvent" v JOIN public."FinanceInvestmentHolding" h ON h.id=v."holdingId" JOIN public."FinanceJournalEntry" e ON e.id=v."journalId" WHERE report_kind='INVESTMENTS' AND v."effectiveDate"<=cutoff
UNION ALL
SELECT a.id::text||':BASELINE:COST',a.id,a."accountId",'COST',a."sourcePostingDate",a.cost,e.id,e."sourceType",e."sourceId",e.reference,a.description FROM public."FinanceAsset" a LEFT JOIN public."FinanceBillLine" b ON b.id=a."billLineId" JOIN public."FinanceJournalEntry" e ON(e."billId"=b."billId" OR e."movementId"=a."fundingMovementId") WHERE report_kind='ASSETS' AND a.state<>'VOIDED' AND a."sourcePostingDate"<=cutoff
UNION ALL
SELECT a.id::text||':BASELINE:CARRYING',a.id,NULL::uuid,'CARRYING',a."sourcePostingDate",a.cost,e.id,e."sourceType",e."sourceId",e.reference,a.description FROM public."FinanceAsset" a LEFT JOIN public."FinanceBillLine" b ON b.id=a."billLineId" JOIN public."FinanceJournalEntry" e ON(e."billId"=b."billId" OR e."movementId"=a."fundingMovementId") WHERE report_kind='ASSETS' AND a.state<>'VOIDED' AND a."sourcePostingDate"<=cutoff
UNION ALL
SELECT v.id::text||':COST',v."assetId",a."accountId",'COST',v."effectiveDate",v."costDelta",v."journalId",'ASSET_MOVEMENT',v."movementId",coalesce(e.reference,m.number),m.description FROM public."FinanceAssetEvent" v JOIN public."FinanceAsset" a ON a.id=v."assetId" JOIN public."FinanceAssetMovement" m ON m.id=v."movementId" LEFT JOIN public."FinanceJournalEntry" e ON e.id=v."journalId" WHERE report_kind='ASSETS' AND v."effectiveDate"<=cutoff AND a.state<>'VOIDED' 
UNION ALL
SELECT v.id::text||':CARRYING',v."assetId",NULL::uuid,'CARRYING',v."effectiveDate",v."costDelta"-v."depreciationDelta",v."journalId",'ASSET_MOVEMENT',v."movementId",coalesce(e.reference,m.number),m.description FROM public."FinanceAssetEvent" v JOIN public."FinanceAsset" a ON a.id=v."assetId" JOIN public."FinanceAssetMovement" m ON m.id=v."movementId" LEFT JOIN public."FinanceJournalEntry" e ON e.id=v."journalId" WHERE report_kind='ASSETS' AND v."effectiveDate"<=cutoff AND a.state<>'VOIDED' 
UNION ALL
SELECT l.id::text||':DEPRECIATION',m."assetId",l."accountId",'DEPRECIATION',e."postingDate",l.credit-l.debit,e.id,e."sourceType",e."sourceId",e.reference,e.description FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" JOIN public."FinanceAssetMovement" m ON m.id=e."assetMovementId" JOIN public."FinanceAccount" a ON a.id=l."accountId" WHERE report_kind='ASSETS' AND a."controlType"='ACCUMULATED_DEPRECIATION' AND e."postingDate"<=cutoff
UNION ALL
SELECT l.id::text||':INCOME',l."projectId",l."accountId",'INCOME',e."postingDate",l.credit-l.debit,e.id,e."sourceType",e."sourceId",e.reference,e.description FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" JOIN public."FinanceAccount" a ON a.id=l."accountId" LEFT JOIN public."FinanceCustomerDocument" c ON c.id=e."customerDocumentId" LEFT JOIN public."FinanceCustomerDocument" original ON original.id=c."reversalOfId" WHERE report_kind='PROJECTS' AND e."postingDate"<=cutoff AND e."sourceType"<>'YEAR_CLOSE' AND (a.type IN('INCOME','OTHER_INCOME'))
UNION ALL
SELECT l.id::text||':DIRECT_COST',l."projectId",l."accountId",'DIRECT_COST',e."postingDate",l.debit-l.credit,e.id,e."sourceType",e."sourceId",e.reference,e.description FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" JOIN public."FinanceAccount" a ON a.id=l."accountId" LEFT JOIN public."FinanceCustomerDocument" c ON c.id=e."customerDocumentId" LEFT JOIN public."FinanceCustomerDocument" original ON original.id=c."reversalOfId" WHERE report_kind='PROJECTS' AND e."postingDate"<=cutoff AND e."sourceType"<>'YEAR_CLOSE' AND (a.type='DIRECT_COST')
UNION ALL
SELECT l.id::text||':OVERHEAD',l."projectId",l."accountId",'OVERHEAD',e."postingDate",l.debit-l.credit,e.id,e."sourceType",e."sourceId",e.reference,e.description FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" JOIN public."FinanceAccount" a ON a.id=l."accountId" LEFT JOIN public."FinanceCustomerDocument" c ON c.id=e."customerDocumentId" LEFT JOIN public."FinanceCustomerDocument" original ON original.id=c."reversalOfId" WHERE report_kind='PROJECTS' AND e."postingDate"<=cutoff AND e."sourceType"<>'YEAR_CLOSE' AND (a.type IN('OPERATING_EXPENSE','OTHER_EXPENSE'))
UNION ALL
SELECT l.id::text||':CONTRIBUTION',l."projectId",l."accountId",'CONTRIBUTION',e."postingDate",l.credit-l.debit,e.id,e."sourceType",e."sourceId",e.reference,e.description FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" JOIN public."FinanceAccount" a ON a.id=l."accountId" LEFT JOIN public."FinanceCustomerDocument" c ON c.id=e."customerDocumentId" LEFT JOIN public."FinanceCustomerDocument" original ON original.id=c."reversalOfId" WHERE report_kind='PROJECTS' AND e."postingDate"<=cutoff AND e."sourceType"<>'YEAR_CLOSE' AND (a.type IN('INCOME','OTHER_INCOME','DIRECT_COST'))
UNION ALL
SELECT l.id::text||':NET_RESULT',l."projectId",l."accountId",'NET_RESULT',e."postingDate",l.credit-l.debit,e.id,e."sourceType",e."sourceId",e.reference,e.description FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" JOIN public."FinanceAccount" a ON a.id=l."accountId" LEFT JOIN public."FinanceCustomerDocument" c ON c.id=e."customerDocumentId" LEFT JOIN public."FinanceCustomerDocument" original ON original.id=c."reversalOfId" WHERE report_kind='PROJECTS' AND e."postingDate"<=cutoff AND e."sourceType"<>'YEAR_CLOSE' AND (a.type IN('INCOME','OTHER_INCOME','DIRECT_COST','OPERATING_EXPENSE','OTHER_EXPENSE'))
UNION ALL
SELECT l.id::text||':NET_BILLED',l."projectId",l."accountId",'NET_BILLED',e."postingDate",l.credit-l.debit,e.id,e."sourceType",e."sourceId",e.reference,e.description FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" JOIN public."FinanceAccount" a ON a.id=l."accountId" LEFT JOIN public."FinanceCustomerDocument" c ON c.id=e."customerDocumentId" LEFT JOIN public."FinanceCustomerDocument" original ON original.id=c."reversalOfId" WHERE report_kind='PROJECTS' AND e."postingDate"<=cutoff AND e."sourceType"<>'YEAR_CLOSE' AND ((a.type IN('INCOME','OTHER_INCOME') OR a."controlType"='DEFERRED_REVENUE') AND (e."sourceType"='INVOICE' OR(e."sourceType"='CUSTOMER_DOCUMENT' AND(c.kind='CUSTOMER_CREDIT' OR(c.kind='REVERSAL' AND original.kind='CUSTOMER_CREDIT')))))
UNION ALL
SELECT l.id::text||':DEFERRED_BILLING',l."projectId",l."accountId",'DEFERRED_BILLING',e."postingDate",l.credit-l.debit,e.id,e."sourceType",e."sourceId",e.reference,e.description FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" JOIN public."FinanceAccount" a ON a.id=l."accountId" LEFT JOIN public."FinanceCustomerDocument" c ON c.id=e."customerDocumentId" LEFT JOIN public."FinanceCustomerDocument" original ON original.id=c."reversalOfId" WHERE report_kind='PROJECTS' AND e."postingDate"<=cutoff AND e."sourceType"<>'YEAR_CLOSE' AND (a."controlType"='DEFERRED_REVENUE' AND (e."sourceType"='INVOICE' OR(e."sourceType"='CUSTOMER_DOCUMENT' AND(c.kind='CUSTOMER_CREDIT' OR(c.kind='REVERSAL' AND original.kind='CUSTOMER_CREDIT')))))
$$;
CREATE FUNCTION encova_finance_rollforward_row_key(report_kind TEXT,entity_id UUID,metric TEXT) RETURNS TEXT LANGUAGE sql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT encode(sha256(convert_to(report_kind||':'||coalesce(entity_id::text,'COMPANY_UNASSIGNED')||':'||metric,'UTF8')),'hex') $$;
CREATE FUNCTION encova_finance_rollforward_controls(report_kind TEXT,date_from DATE,cutoff DATE) RETURNS TABLE("accountId" UUID,code TEXT,name TEXT,active BOOLEAN,"openingSubledger" NUMERIC,"openingControl" NUMERIC,"openingDifference" NUMERIC,"closingSubledger" NUMERIC,"closingControl" NUMERIC,"closingDifference" NUMERIC) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 WITH expected AS MATERIALIZED(SELECT "accountId",coalesce(sum(delta) FILTER(WHERE "effectiveDate"<date_from),0) AS opening,sum(delta) AS closing FROM public.encova_finance_rollforward_events(report_kind,cutoff) WHERE "accountId" IS NOT NULL AND(report_kind IN('FUNDING','LOANS','ADVANCES') OR report_kind='INVESTMENTS' AND metric IN('CARRYING','INCOME_RECEIVABLE') OR report_kind='ASSETS' AND metric IN('COST','DEPRECIATION')) GROUP BY "accountId"),
 accounts AS MATERIALIZED(SELECT a.* FROM public."FinanceAccount" a WHERE a.currency='PKR' AND CASE report_kind WHEN 'FUNDING' THEN a."controlType" IN('CAPITAL','DISTRIBUTION','FOUNDER_PAYABLE') WHEN 'LOANS' THEN a."controlType" IN('LOAN_PAYABLE','LOAN_RECEIVABLE','INTEREST_PAYABLE','INTEREST_RECEIVABLE') WHEN 'ADVANCES' THEN a."controlType" IN('CLIENT_ADVANCE','SUPPLIER_ADVANCE') WHEN 'INVESTMENTS' THEN a."controlType" IN('INVESTMENT','INVESTMENT_INCOME_RECEIVABLE') WHEN 'ASSETS' THEN a."controlType" IN('FIXED_ASSET','ACCUMULATED_DEPRECIATION') ELSE false END),
 actual AS(SELECT a.id,coalesce(sum(CASE WHEN a."controlType" IN('CAPITAL','FOUNDER_PAYABLE','LOAN_PAYABLE','INTEREST_PAYABLE','CLIENT_ADVANCE','ACCUMULATED_DEPRECIATION') THEN l.credit-l.debit ELSE l.debit-l.credit END) FILTER(WHERE e."postingDate"<date_from),0) AS opening,coalesce(sum(CASE WHEN a."controlType" IN('CAPITAL','FOUNDER_PAYABLE','LOAN_PAYABLE','INTEREST_PAYABLE','CLIENT_ADVANCE','ACCUMULATED_DEPRECIATION') THEN l.credit-l.debit ELSE l.debit-l.credit END) FILTER(WHERE e."postingDate"<=cutoff),0) AS closing FROM accounts a LEFT JOIN public."FinanceJournalLine" l ON l."accountId"=a.id LEFT JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" AND e."postingDate"<=cutoff GROUP BY a.id)
 SELECT a.id,a.code,a.name,a.active,coalesce(x.opening,0),v.opening,coalesce(x.opening,0)-v.opening,coalesce(x.closing,0),v.closing,coalesce(x.closing,0)-v.closing FROM accounts a JOIN actual v ON v.id=a.id LEFT JOIN expected x ON x."accountId"=a.id
$$;
CREATE FUNCTION encova_finance_rollforward_groups(report_kind TEXT,cutoff DATE) RETURNS TABLE("rowKey" TEXT,"entityId" UUID,name TEXT,number TEXT,active BOOLEAN,"entityHref" TEXT,metric TEXT,unit TEXT,"eventCount" INTEGER,"accountCount" INTEGER) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 WITH dimensions AS(SELECT "entityId",metric,count(*)::integer AS events,count(DISTINCT "accountId")::integer AS accounts FROM public.encova_finance_rollforward_events(report_kind,cutoff) GROUP BY "entityId",metric)
 SELECT public.encova_finance_rollforward_row_key(report_kind,d."entityId",d.metric),d."entityId",CASE report_kind WHEN 'PROJECTS' THEN coalesce(p.name,'Company unassigned') WHEN 'FUNDING' THEN party.name WHEN 'LOANS' THEN loan.name WHEN 'INVESTMENTS' THEN holding.name WHEN 'ASSETS' THEN asset.tag ELSE coalesce(c.number,s.number) END,CASE report_kind WHEN 'LOANS' THEN loan.number WHEN 'INVESTMENTS' THEN holding.number WHEN 'ASSETS' THEN asset.number ELSE NULL END,CASE report_kind WHEN 'PROJECTS' THEN p."archivedAt" IS NULL WHEN 'FUNDING' THEN party.active WHEN 'LOANS' THEN loan.active WHEN 'INVESTMENTS' THEN holding.active WHEN 'ASSETS' THEN asset.state<>'VOIDED' ELSE true END,CASE WHEN d."entityId" IS NULL THEN NULL WHEN report_kind='PROJECTS' THEN '/finance/projects/'||p.id::text WHEN report_kind='FUNDING' THEN '/finance/parties/'||party.id::text WHEN report_kind='LOANS' THEN '/finance/loans/'||loan.id::text WHEN report_kind='INVESTMENTS' THEN '/finance/investments/'||holding.id::text WHEN report_kind='ASSETS' THEN '/finance/assets/'||asset.id::text ELSE '/finance/posted-sources/'||coalesce(ce.id,se.id)::text END,d.metric,CASE WHEN d.metric='UNITS' THEN 'UNITS' ELSE 'PKR' END,d.events,d.accounts FROM dimensions d
 LEFT JOIN public."Project" p ON report_kind='PROJECTS' AND p.id=d."entityId" LEFT JOIN public."FinanceParty" party ON report_kind='FUNDING' AND party.id=d."entityId" LEFT JOIN public."FinanceLoan" loan ON report_kind='LOANS' AND loan.id=d."entityId" LEFT JOIN public."FinanceInvestmentHolding" holding ON report_kind='INVESTMENTS' AND holding.id=d."entityId" LEFT JOIN public."FinanceAsset" asset ON report_kind='ASSETS' AND asset.id=d."entityId"
 LEFT JOIN public."FinanceCustomerDocument" c ON report_kind='ADVANCES' AND d.metric='CLIENT_ADVANCE' AND c.id=d."entityId" LEFT JOIN public."FinanceSupplierDocument" s ON report_kind='ADVANCES' AND d.metric='SUPPLIER_ADVANCE' AND s.id=d."entityId" LEFT JOIN public."FinanceJournalEntry" ce ON ce."customerDocumentId"=c.id LEFT JOIN public."FinanceJournalEntry" se ON se."supplierDocumentId"=s.id
$$;
CREATE FUNCTION encova_finance_rollforward_report(report_kind TEXT,date_from DATE,cutoff DATE,search TEXT,requested_page INTEGER,issue_page INTEGER) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE result JSONB;BEGIN
 WITH events AS MATERIALIZED(SELECT * FROM public.encova_finance_rollforward_events(report_kind,cutoff)),groups AS MATERIALIZED(SELECT * FROM public.encova_finance_rollforward_groups(report_kind,cutoff)),
 positions AS MATERIALIZED(SELECT "entityId",metric,coalesce(sum(delta) FILTER(WHERE "effectiveDate"<date_from),0) AS opening,coalesce(sum(delta) FILTER(WHERE "effectiveDate">=date_from AND delta>0),0) AS increases,-coalesce(sum(delta) FILTER(WHERE "effectiveDate">=date_from AND delta<0),0) AS decreases,sum(delta) AS closing,count(*) FILTER(WHERE "effectiveDate">=date_from)::integer AS period_events FROM events GROUP BY "entityId",metric),
 full_rows AS MATERIALIZED(SELECT g.*,v.opening,v.increases,v.decreases,v.increases-v.decreases AS net,v.closing,v.period_events FROM groups g JOIN positions v ON v."entityId" IS NOT DISTINCT FROM g."entityId" AND v.metric=g.metric),
 controls AS MATERIALIZED(SELECT * FROM public.encova_finance_rollforward_controls(report_kind,date_from,cutoff)),books AS(SELECT coalesce(sum(l.debit-l.credit) FILTER(WHERE e."postingDate"<date_from),0) AS opening,coalesce(sum(l.debit-l.credit),0) AS closing FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" WHERE e."postingDate"<=cutoff),
 diagnostics AS MATERIALIZED(SELECT 'ACCOUNT:'||"accountId"::text AS "issueKey",'ACCOUNT'::text AS scope,code||' · '||name AS label,"accountId",NULL::text AS "rowKey",NULL::text AS metric,"openingSubledger","openingControl","openingDifference","closingSubledger","closingControl","closingDifference" FROM controls WHERE "openingDifference"<>0 OR "closingDifference"<>0
 UNION ALL SELECT 'ROW:'||"rowKey",'NEGATIVE_ROW',coalesce(number||' · ','')||name,NULL::uuid,"rowKey",metric,opening,NULL::numeric,NULL::numeric,closing,NULL::numeric,closing FROM full_rows WHERE report_kind<>'PROJECTS' AND closing<0
 UNION ALL SELECT 'BOOK','BOOK','Company journal balance',NULL::uuid,NULL::text,NULL::text,NULL::numeric,NULL::numeric,opening,NULL::numeric,NULL::numeric,closing FROM books WHERE opening<>0 OR closing<>0),
 issue_counts AS(SELECT count(*)::integer AS total,greatest(1,ceil(count(*)/25.0)::integer) AS pages FROM diagnostics),ip AS(SELECT *,least(issue_page,pages) AS page FROM issue_counts),bounded_issues AS(SELECT * FROM diagnostics ORDER BY scope,label,"issueKey" LIMIT 25 OFFSET((SELECT page FROM ip)-1)*25),issue_rows AS(SELECT coalesce(jsonb_agg(jsonb_build_object('issueKey',"issueKey",'scope',scope,'label',label,'accountId',"accountId",'rowKey',"rowKey",'metric',metric,'openingSubledger',CASE WHEN "openingSubledger" IS NOT NULL THEN round("openingSubledger",2)::text END,'openingControl',CASE WHEN "openingControl" IS NOT NULL THEN round("openingControl",2)::text END,'openingDifference',CASE WHEN "openingDifference" IS NOT NULL THEN round("openingDifference",2)::text END,'closingSubledger',CASE WHEN "closingSubledger" IS NOT NULL THEN round("closingSubledger",2)::text END,'closingControl',CASE WHEN "closingControl" IS NOT NULL THEN round("closingControl",2)::text END,'closingDifference',CASE WHEN "closingDifference" IS NOT NULL THEN round("closingDifference",2)::text END) ORDER BY scope,label,"issueKey"),'[]'::jsonb) AS items FROM bounded_issues),
 totals AS(SELECT coalesce(jsonb_agg(jsonb_build_object('metric',metric,'unit','PKR','openingBalance',round(opening,2)::text,'increases',round(increases,2)::text,'decreases',round(decreases,2)::text,'periodNet',round(increases-decreases,2)::text,'closingBalance',round(closing,2)::text) ORDER BY metric),'[]'::jsonb) AS items FROM(SELECT metric,sum(opening) AS opening,sum(increases) AS increases,sum(decreases) AS decreases,sum(closing) AS closing FROM full_rows WHERE metric<>'UNITS' GROUP BY metric)b),
 displayed AS MATERIALIZED(SELECT * FROM full_rows WHERE(opening<>0 OR period_events>0 OR closing<>0) AND concat_ws(' ',name,number,metric,"entityId") ILIKE '%'||search||'%'),counts AS(SELECT count(*)::integer AS total,greatest(1,ceil(count(*)/25.0)::integer) AS pages FROM displayed),paging AS(SELECT *,least(requested_page,pages) AS page FROM counts),bounded AS(SELECT * FROM displayed ORDER BY name,number NULLS FIRST,"entityId" NULLS FIRST,metric LIMIT 25 OFFSET((SELECT page FROM paging)-1)*25),rows AS(SELECT coalesce(jsonb_agg(jsonb_build_object('rowKey',"rowKey",'entityId',"entityId",'name',name,'number',number,'active',active,'entityHref',"entityHref",'metric',metric,'unit',unit,'eventCount',"eventCount",'accountCount',"accountCount",'periodEventCount',period_events,'openingBalance',round(opening,CASE WHEN unit='UNITS' THEN 6 ELSE 2 END)::text,'increases',round(increases,CASE WHEN unit='UNITS' THEN 6 ELSE 2 END)::text,'decreases',round(decreases,CASE WHEN unit='UNITS' THEN 6 ELSE 2 END)::text,'periodNet',round(net,CASE WHEN unit='UNITS' THEN 6 ELSE 2 END)::text,'closingBalance',round(closing,CASE WHEN unit='UNITS' THEN 6 ELSE 2 END)::text) ORDER BY name,number NULLS FIRST,"entityId" NULLS FIRST,metric),'[]'::jsonb) AS items FROM bounded),
 proof AS(SELECT encode(sha256(convert_to(coalesce(jsonb_agg(jsonb_build_object('key',"eventKey",'entity',"entityId",'account',"accountId",'metric',metric,'date',"effectiveDate",'delta',delta::text,'journalId',"journalId",'sourceType',"sourceType",'sourceId',"sourceId") ORDER BY "eventKey"),'[]'::jsonb)::text,'UTF8')),'hex') AS digest FROM events)
 SELECT jsonb_build_object('metadata',public.encova_finance_report_metadata(date_from,cutoff,jsonb_build_object('report','ROLL_FORWARD','kind',report_kind,'displaySearch',search,'eventDigest',proof.digest,'registerBasis',CASE WHEN report_kind='ASSETS' THEN 'Current retained register allocation of actual historical purchase cost; unassigned GL cost remains an explicit control issue' ELSE 'Actual posted dated events' END)),'kind',report_kind,'totals',totals.items,'reconciliation',jsonb_build_object('ready',ip.total=0,'issueCount',ip.total,'controlCount',(SELECT count(*) FROM controls),'negativeRowCount',(SELECT count(*) FROM diagnostics WHERE scope='NEGATIVE_ROW'),'openingBookDifference',round(books.opening,2)::text,'closingBookDifference',round(books.closing,2)::text,'issues',issue_rows.items,'page',ip.page,'pages',ip.pages),'items',rows.items,'total',paging.total,'page',paging.page,'pages',paging.pages) INTO result FROM paging CROSS JOIN rows CROSS JOIN totals CROSS JOIN ip CROSS JOIN issue_rows CROSS JOIN proof CROSS JOIN books;RETURN result;
END $$;
CREATE FUNCTION encova_finance_rollforward_history(report_kind TEXT,date_from DATE,cutoff DATE,row_key TEXT,requested_page INTEGER) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE dimension JSONB;result JSONB;BEGIN
 SELECT to_jsonb(g) INTO dimension FROM public.encova_finance_rollforward_groups(report_kind,cutoff)g WHERE g."rowKey"=row_key;IF dimension IS NULL THEN RAISE EXCEPTION 'FINANCE_NOT_FOUND' USING ERRCODE='P0001';END IF;
 WITH actual AS MATERIALIZED(SELECT v.*,e."postedAt",a.code,a.name AS "accountName",sum(v.delta) OVER(ORDER BY v."effectiveDate",coalesce(e."postedAt",'-infinity'::timestamptz),v."eventKey" ROWS UNBOUNDED PRECEDING) AS running FROM public.encova_finance_rollforward_events(report_kind,cutoff)v LEFT JOIN public."FinanceJournalEntry" e ON e.id=v."journalId" LEFT JOIN public."FinanceAccount" a ON a.id=v."accountId" WHERE public.encova_finance_rollforward_row_key(report_kind,v."entityId",v.metric)=row_key),
 balances AS(SELECT coalesce(sum(delta) FILTER(WHERE "effectiveDate"<date_from),0) AS opening,coalesce(sum(delta),0) AS closing FROM actual),period AS MATERIALIZED(SELECT * FROM actual WHERE "effectiveDate">=date_from),counts AS(SELECT count(*)::integer AS total,greatest(1,ceil(count(*)/25.0)::integer) AS pages FROM period),paging AS(SELECT *,least(requested_page,pages) AS page FROM counts),bounded AS(SELECT * FROM period ORDER BY "effectiveDate",coalesce("postedAt",'-infinity'::timestamptz),"eventKey" LIMIT 25 OFFSET((SELECT page FROM paging)-1)*25),rows AS(SELECT coalesce(jsonb_agg(jsonb_build_object('eventKey',"eventKey",'effectiveDate',"effectiveDate",'accountId',"accountId",'code',code,'accountName',"accountName",'amount',round(delta,CASE WHEN dimension->>'unit'='UNITS' THEN 6 ELSE 2 END)::text,'runningBalance',round(running,CASE WHEN dimension->>'unit'='UNITS' THEN 6 ELSE 2 END)::text,'journalId',"journalId",'sourceType',"sourceType",'sourceId',"sourceId",'reference',reference,'description',description) ORDER BY "effectiveDate",coalesce("postedAt",'-infinity'::timestamptz),"eventKey"),'[]'::jsonb) AS items FROM bounded)
 SELECT jsonb_build_object('metadata',public.encova_finance_report_metadata(date_from,cutoff,jsonb_build_object('report','ROLL_FORWARD_HISTORY','kind',report_kind,'rowKey',row_key)),'kind',report_kind,'dimension',dimension,'openingBalance',round(b.opening,CASE WHEN dimension->>'unit'='UNITS' THEN 6 ELSE 2 END)::text,'closingBalance',round(b.closing,CASE WHEN dimension->>'unit'='UNITS' THEN 6 ELSE 2 END)::text,'items',rows.items,'total',paging.total,'page',paging.page,'pages',paging.pages) INTO result FROM balances b CROSS JOIN paging CROSS JOIN rows;RETURN result;
END $$;
CREATE FUNCTION encova_finance_rollforward_read(actor UUID,report_kind TEXT,operation TEXT,input JSONB) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE date_from DATE;cutoff DATE;BEGIN
 IF NOT EXISTS(SELECT 1 FROM public."Person" WHERE id=actor AND role='SUPER_ADMIN' AND status='ACTIVE') OR NOT EXISTS(SELECT 1 FROM public."FinanceGrant" WHERE "userId"=actor AND "revokedAt" IS NULL) THEN RAISE EXCEPTION 'FINANCE_FORBIDDEN' USING ERRCODE='P0001';END IF;
 IF report_kind IS NULL OR report_kind NOT IN('PROJECTS','FUNDING','LOANS','INVESTMENTS','ASSETS','ADVANCES') OR operation IS NULL OR operation NOT IN('REPORT','HISTORY') OR jsonb_typeof(input) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM unnest(ARRAY['from','to'])k WHERE jsonb_typeof(input->k) IS DISTINCT FROM 'string') OR input->>'from'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR input->>'to'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR jsonb_typeof(input->'page') IS DISTINCT FROM 'number' OR(input->>'page')::integer NOT BETWEEN 1 AND 10000 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 date_from:=(input->>'from')::date;cutoff:=(input->>'to')::date;IF date_from<DATE '0001-01-01' OR cutoff>DATE '9999-12-31' OR date_from>cutoff THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 IF operation='HISTORY' THEN
  IF input-ARRAY['from','to','rowKey','page']<>'{}'::jsonb OR jsonb_typeof(input->'rowKey') IS DISTINCT FROM 'string' OR input->>'rowKey'!~'^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  RETURN public.encova_finance_rollforward_history(report_kind,date_from,cutoff,input->>'rowKey',(input->>'page')::integer);
 END IF;
 IF input-ARRAY['from','to','q','page','issuePage']<>'{}'::jsonb OR jsonb_typeof(input->'q') IS DISTINCT FROM 'string' OR length(input->>'q')>100 OR jsonb_typeof(input->'issuePage') IS DISTINCT FROM 'number' OR(input->>'issuePage')::integer NOT BETWEEN 1 AND 10000 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 RETURN public.encova_finance_rollforward_report(report_kind,date_from,cutoff,input->>'q',(input->>'page')::integer,(input->>'issuePage')::integer);
 EXCEPTION WHEN data_exception THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END $$;
DO $$ DECLARE f RECORD;r TEXT;BEGIN
 FOR f IN SELECT oid::regprocedure AS signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND(proname LIKE 'encova_finance_rollforward_%' OR proname='encova_finance_posted_source_read') LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);FOREACH r IN ARRAY ARRAY['encova_app','anon','authenticated'] LOOP IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r);END IF;END LOOP;END LOOP;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='encova_app') THEN GRANT EXECUTE ON FUNCTION public.encova_finance_rollforward_read(UUID,TEXT,TEXT,JSONB),public.encova_finance_posted_source_read(UUID,JSONB) TO encova_app;END IF;
END $$;
COMMIT;
